answer_code:
function createEmitter() {
  const listeners = new Map();
  return {
    on(name, fn) {
      if (!listeners.has(name)) {
        listeners.set(name, []);
      }
      listeners.get(name).push(fn);
    },
    off(name, fn) {
      const list = listeners.get(name);
      if (!list) {
        return;
      }
      const i = list.indexOf(fn);
      if (i >= 0) {
        list.splice(i, 1);
      }
    },
    emit(name, ...args) {
      const list = listeners.get(name);
      if (!list) {
        return 0;
      }
      for (const fn of list.slice()) {
        fn(...args);
      }
      return list.length;
    },
  };
}

