answer_code:
async function* paginate(fetchPage) {
  let cursor = null;
  while (true) {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      yield item;
    }
    if (page.next === null) {
      return;
    }
    cursor = page.next;
  }
}

