  if (isPlainObject(value) && isPlainObject(merged[key])) {
    merged[key] = deepMerge(merged[key], value);  // 2. 両方オブジェクトなら奥へ
  } else {
    merged[key] = value;               // 3. それ以外は patch が勝つ
  }
}
