answer_code:
function paginate(totalItems, perPage, page) {
  const totalPages = Math.ceil(totalItems / perPage);
  const current = Math.min(Math.max(page, 1), Math.max(totalPages, 1));
  const startIndex = Math.min((current - 1) * perPage, totalItems);
  const endIndex = Math.min(startIndex + perPage, totalItems);
  return { totalPages, page: current, startIndex, endIndex };
}

