      throw new RangeError(`${name} は有限の正の数でなければなりません: ${v}`);
    }
  }

  get width() {
    return this._width;
  }
  set width(v) {
    Rectangle.#validate(v, "width");
    this._width = v;
  }

  get height() {
    return this._height;
  }
  set height(v) {
    Rectangle.#validate(v, "height");
    this._height = v;
  }

  get area() {
    return this._width * this._height;
  }
}

