function protoChainNames(obj) {
  const names = [];
  let proto = Object.getPrototypeOf(obj);
  while (proto !== null) {
    const ctor = proto.constructor;
    names.push(ctor && ctor.name ? ctor.name : "(anonymous)");
    proto = Object.getPrototypeOf(proto);
  }
  return names;
}

