answer_code:
class LinkedList {
  #head = null;
  #tail = null;
  #size = 0;

  push(value) {
    const node = { value, next: null };
    if (this.#tail === null) {
      this.#head = node;
      this.#tail = node;
    } else {
      this.#tail.next = node;
      this.#tail = node;
    }
    this.#size++;
    return this;
  }

  unshift(value) {
    const node = { value, next: this.#head };
    this.#head = node;
    if (this.#tail === null) this.#tail = node;
    this.#size++;
    return this;
  }

  shift() {
    if (this.#head === null) return undefined;
    const node = this.#head;
    this.#head = node.next;
    if (this.#head === null) this.#tail = null;
    node.next = null;
    this.#size--;
    return node.value;
  }

  toArray() {
    const out = [];
    for (let n = this.#head; n !== null; n = n.next) {
      out.push(n.value);
    }
    return out;
  }

  get size() {
    return this.#size;
  }
}

