answer_code:
class MinHeap {
  #data = [];

  get size() {
    return this.#data.length;
  }

  peek() {
    return this.#data.length > 0 ? this.#data[0] : undefined;
  }

  push(v) {
    const d = this.#data;
    d.push(v);
    let i = d.length - 1;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (d[parent] <= d[i]) break;
      [d[parent], d[i]] = [d[i], d[parent]];
      i = parent;
    }
    return this;
  }

  pop() {
    const d = this.#data;
    if (d.length === 0) return undefined;
    const top = d[0];
    const last = d.pop();
    if (d.length > 0) {
      d[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = 2 * i + 2;
        let smallest = i;
        if (l < d.length && d[l] < d[smallest]) smallest = l;
        if (r < d.length && d[r] < d[smallest]) smallest = r;
        if (smallest === i) break;
        [d[i], d[smallest]] = [d[smallest], d[i]];
        i = smallest;
      }
    }
    return top;
  }
}

