function hasCycle(root) {
  const path = new Set();

  function walk(value) {
    if (value === null || typeof value !== "object") return false;
    if (path.has(value)) return true;

    path.add(value);
    for (const key of Object.keys(value)) {
      if (walk(value[key])) return true;
    }
    path.delete(value);

    return false;
  }

  return walk(root);
}

