function createMachine(spec) {
  let current = spec.initial;

  function can(event) {
    const node = spec.states[current];
    if (!node || !node.on) return false;
    return Object.prototype.hasOwnProperty.call(node.on, event);
  }

  return {
    get state() {
      return current;
    },
    can,
    send(event) {
      if (!can(event)) return false;
      current = spec.states[current].on[event];
      return true;
    }
  };
}
